int live;int destroyed;int begins;int ends;
struct R{int a[3];R(){++live;a[0]=1;a[1]=2;a[2]=3;}~R(){--live;++destroyed;}int*begin(){++begins;return a;}int*end(){++ends;return a+3;}};
int main(){int n=0;for(auto x:R()){if(live!=1||destroyed)return 1;n+=x;}return n!=6||live||destroyed!=1||begins!=1||ends!=1;}

